using Scheduling.Legacy;

namespace Scheduling;

/// <summary>Sends reminders for upcoming jobs.</summary>
public sealed class ReminderSender
{
    public bool Send(Job job, string recipient)
    {
        // TODO: localise the reminder text per recipient
        return NotifyApiV2.Send(new Notification
        {
            Recipient = recipient,
            Body = $"Reminder for {job.Id}"
        });
    }
}
